window.LD=window.LD||{};window.LD["party/p4"]={"id":"p4","name":"Juniper's Shields","poss":"Juniper's Shields'","members":["h10","h12","h18"],"leader":"h10","morale":100,"disposition":"friendly","motto":"We bicker. We don't break.","banner":{"c1":"#e8e8e8","c2":"#2f9e9e","emblem":"shield"},"loc":"whitepeak","loc_name":"Whitepeak Pass","goal":{"text":"to earn 450 silver between them before the season ends","kind":"purse","done":78,"progress":"1,134 silver, past the 450 aimed for","missed":false,"crew":"Juniper's Shields","party":"p4"},"vows":[{"text":"to repay Sunlit Quills","day":15,"state":"kept","ended":56,"through":false,"progress":"kept on day 26 of season 2","crew":"Juniper's Shields","party":"p4"},{"text":"never to retreat","day":31,"state":"broken","ended":33,"through":false,"progress":"broken on day 3 of season 2","crew":"Juniper's Shields","party":"p4"}],"doing":"last seen hunting in Whitepeak Pass","progress":null,"today":["Fought 1 fight: won 1; 3 foes down.","XP: Juniper +599, Ash +599, Isolde +599 (level 22!).","Came away with 19 pelts, 6 fangs & claws, 2 wolf haunches.","Ate 3 rations."],"fights_today":["f257"],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":234,"season":{"wins":14,"bosses":0,"floors":6,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30},"career":{"wins":34,"bosses":0,"floors":16,"gold":0,"deaths":0,"fled":3,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"donkey_cart","name":"Princess","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":36,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"donkey","name":"Parsnip","label":"donkey","colour":"brown","owner":null},"paid":[["Ash",18],["Juniper",16]]},"pace_gap":0,"rels":[{"party":"p7","score":100},{"party":"p3","score":96},{"party":"p2","score":48},{"party":"p1","score":45},{"party":"p6","score":32},{"party":"p5","score":24}],"events":[{"id":"e30","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Juniper and Ash shake on it at The Gilded Flagon: they are now Juniper's Shields. (Friendly, by the look of them.)","heroes":["h10","h12"],"parties":["p4"],"loc":"ironhaven","wx":"fog"},{"id":"e398","day":11,"season":1,"sday":11,"kind":"road","imp":4,"text":"On a lonely stretch of the road to Cragtooth Warren, a crow lands on Isolde's shoulder, looks at the sky and croaks one word, 'Ready.' Isolde is not sure what for, but feels it all the way home.","heroes":["h18","h10","h12"],"parties":["p4"],"road":"cragtooth_warren~ironhaven","road_rec":"r89"},{"id":"e530","day":15,"season":1,"sday":15,"kind":"rescue","imp":4,"text":"RESCUE in Cragtooth Warren: Quill (Taylor's hero) finds Juniper (Robin's hero) bleeding in the dark and does not walk past. 2 potions later, Juniper is breathing properly.","heroes":["h11","h10","h20","h12","h18"],"parties":["p2","p4"],"loc":"cragtooth_warren","rescuers":["h11","h20"]},{"id":"e756","day":20,"season":1,"sday":20,"kind":"road","imp":3,"text":"Hetty Brimble teaches Ash how to trim a wick so it burns steady. Ash goes into the dark feeling braver than before.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"bleakmarsh~thornmere_ruins","traveller":"hetty","road_rec":"r149"},{"id":"e757","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"Juniper says a quiet grace over the fire. Isolde bows too, a beat late. One quiet Devout, and done.","heroes":["h10","h18"],"parties":["p4"],"loc":"thornmere_ruins","skill":"devout"},{"id":"e792","day":21,"season":1,"sday":21,"kind":"delve","imp":1,"text":"Juniper's Shields descend into Thornmere Ruins, untouched (0%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e798","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"Juniper's Shields defeat 3 Bog Crawlers and 2 Will-o'-Wisps in the reed beds on floor 1 of Thornmere Ruins. The last will-o'-wisp bolts. The will-o'-wisp took Juniper's Turn Undead full on and was never the same after. Loot: 7 chitin, 2 bottled wisplight, 4 bog crawler claws.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f64","foes":["bog_crawler","wisp","wisp"],"where":"in the reed beds on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"plain"},{"id":"e800","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"In the tithe barn on floor 1 of Thornmere Ruins, Juniper's Shields square up to 4 Bog Crawlers and a Will-o'-Wisp and carry the day. The last bog crawler doesn't stay to see the end. Isolde put Caltrops where it would hit four bog crawlers, and it did. Ask the others what won it: Juniper's Oath of Light. Loot: 10 chitin, 4 bog crawler claws, 2 bottled wisplight.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f65","foes":["bog_crawler","bog_crawler","bog_crawler"],"where":"in the tithe barn on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-46},{"id":"e801","day":21,"season":1,"sday":21,"kind":"fight","imp":1,"text":"It's 2 Bog Crawlers and a Will-o'-Wisp against Juniper's Shields in the gatehouse yard on floor 1 of Thornmere Ruins, and it isn't close. Ask anyone when it turned: Juniper's Mark of the Oath. Loot: 2 bog crawler claws, 2 chitin.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f66","foes":["wisp","bog_crawler","bog_crawler"],"where":"in the gatehouse yard on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e802","day":21,"season":1,"sday":21,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Thornmere Ruins at a steady pace: 5 rooms (the temple porch, the reed beds, the tithe barn and 2 more).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":5,"size":3,"floor":1,"traps":1,"sprung":1,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":3,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e803","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Juniper trips a wire on the way to the privy. A bell rings. Isolde wakes and says 'that's one'.","heroes":["h18","h10"],"parties":["p4"],"loc":"thornmere_ruins","skill":"first_one_through"},{"id":"e822","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Juniper sleeps on the side of the fire nearest Ash. Everyone does now. (Living Fortress, if anyone's asking.)","heroes":["h12","h10"],"parties":["p4"],"loc":"thornmere_ruins","skill":"living_fortress"},{"id":"e827","day":21,"season":1,"sday":21,"kind":"big_move","imp":3,"text":"Ash has put the day they became a Guardian into a song, and says every word is true, roughly. On the table: Juniper's Shields +53 party renown (5th to 4th among the crews).","heroes":["h10","h12","h18"],"parties":["p4"],"party_moves":[{"party":"p4","gain":53,"from":5,"to":4}],"cause":"e819"},{"id":"e848","day":22,"season":1,"sday":22,"kind":"fight","imp":2,"text":"With Isolde hitting hardest, Juniper's Shields handle 2 Will-o'-Wisps, a Bog Crawler and a Swamp Troll in the drowned nave on floor 1 of Thornmere Ruins. The last will-o'-wisp doesn't stay to see the end. Ash picked out the swamp troll and finished the job with Sunder. Isolde kept them off everyone with The First One Through. Loot: 10 silver each, 2 bottled wisplight, 2 troll hide.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f74","foes":["wisp","bog_crawler","swamp_troll"],"where":"in the drowned nave on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-51},{"id":"e849","day":22,"season":1,"sday":22,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Thornmere Ruins at a steady pace: 3 rooms (the causeway, the scriptorium, the drowned nave).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e871","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Isolde rigs a little deadfall over the cooking pot so the crows learn some manners.","heroes":["h18"],"parties":["p4"],"loc":"thornmere_ruins","skill":"first_one_through"},{"id":"e872","day":22,"season":1,"sday":22,"kind":"campfire","imp":1,"text":"Isolde carves Juniper's initials into the campfire log. Juniper carves a rude drawing next to them. Friendship.","heroes":["h18","h10"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e881","day":22,"season":1,"sday":22,"kind":"goal_done","imp":4,"text":"Juniper's Shields can cross it off: earn 300 silver between them before the season ends. Drinks are on them. XP: Juniper +960 (level 13!), Ash +960 (level 13!), Isolde +960 (level 13!).","heroes":["h10","h12","h18"],"parties":["p4"],"xp":{"h10":960,"h12":960,"h18":960}},{"id":"e905","day":23,"season":1,"sday":23,"kind":"fight","imp":2,"text":"It takes Juniper's Shields 6 rounds to scrape past 3 Sirens and a Will-o'-Wisp in the choir loft on floor 1 of Thornmere Ruins. Isolde's First One Through knocked half the fight out of the siren. Taunt did more for this fight than the scoreboard shows. That was Ash. Loot: 1 gem, 14 trinkets, 14 sea grapes.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f77","foes":["siren","siren","wisp"],"where":"in the choir loft on floor 1 of Thornmere Ruins","won":true,"close":true,"shape":"close","reworded":-21},{"id":"e906","day":23,"season":1,"sday":23,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Thornmere Ruins at a steady pace: 4 rooms (a hidden room behind the drowned nave, the choir loft, the porters' lodge and 1 more).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e907","day":23,"season":1,"sday":23,"kind":"night","imp":2,"text":"Something small and clever gets into Juniper's Shields' camp on floor 1 of Thornmere Ruins overnight. Ash wakes up 3 silver and 2 rations lighter.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e925","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Juniper sings an evening hymn by the fire. Even Ash, a sceptic, hums the last line. A small Hymn Singer, cast without looking up.","heroes":["h10","h12"],"parties":["p4"],"loc":"thornmere_ruins","skill":"hymn_singer"},{"id":"e946","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Thornmere Ruins at a push pace: 3 rooms (the wayside cross, the sunken stair, a worn spiral down from the choir, going under the water).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e947","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"Isolde charms the cooking pot so it never boils over. Dinner is calmer. Hedge Wizardry, cast gently, for once.","heroes":["h18"],"parties":["p4"],"loc":"thornmere_ruins","skill":"hedge_wizard"},{"id":"e965","day":24,"season":1,"sday":24,"kind":"campfire","imp":1,"text":"Two weeks into Juniper's Shields, Juniper can tell Isolde's boots from everyone else's by the sound.","heroes":["h10","h18"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e966","day":24,"season":1,"sday":24,"kind":"campfire","imp":1,"text":"Two weeks on the road together: Ash and Isolde now finish each other's complaints.","heroes":["h12","h18"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e968","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"Ash briefs the crew on which other parties are feuding, and why. Juniper takes notes.","heroes":["h12","h10"],"parties":["p4"],"loc":"thornmere_ruins","skill":"rumourmonger"},{"id":"e995","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the pilgrims' hall, the temple fish ponds).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e996","day":25,"season":1,"sday":25,"kind":"boss_race","imp":3,"text":"Mother Thornmere has visitors coming. Juniper's Shields and The Tidal Ledger are both on the way to Thornmere Ruins, and nobody is waiting for the others.","heroes":["h10","h12","h18","h7","h19","h2","h14"],"parties":["p4","p7"],"loc":"thornmere_ruins"},{"id":"e1018","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the chandlery, the sacristy).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1020","day":26,"season":1,"sday":26,"kind":"talent","imp":2,"text":"Juniper teaches Isolde to call a target in one word. Isolde picks 'that'.","heroes":["h10","h18"],"parties":["p4"],"loc":"thornmere_ruins","skill":"mark_of_the_oath","wx":"rain"},{"id":"e1030","day":26,"season":1,"sday":26,"kind":"meet","imp":2,"text":"Juniper's Shields and The Tidal Ledger share a fire in Thornmere Ruins. Isolde shares jerky.","heroes":["h10","h12","h18","h7","h19","h2","h14"],"parties":["p4","p7"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1060","day":27,"season":1,"sday":27,"kind":"delve_done","imp":3,"text":"Juniper's Shields climb out at last, 7 days older and a good deal dirtier. They cleared 19 rooms, made it to floor 1, put 33% of it on paper, found the gatehouse yard, the drowned nave, a hidden room behind the drowned nave and 1 more good room, split 161 silver on the way up and turned back because the rations would only just see them home. Pin it to the board: Thornmere Ruins is partly explored (37%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins","days":7,"bottom":false,"rooms":["the gatehouse yard","the drowned nave"],"gold":161,"turn":"supplies"},{"id":"e1066","day":27,"season":1,"sday":27,"kind":"boss_race","imp":2,"text":"Juniper's Shields give up on Mother Thornmere for now, and the race to Thornmere Ruins belongs to The Tidal Ledger.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e1074","day":27,"season":1,"sday":27,"kind":"campfire","imp":2,"text":"Isolde saves Juniper the crispy bits from the pan without a word.","heroes":["h10","h18"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e1103","day":28,"season":1,"sday":28,"kind":"meet","imp":1,"text":"Juniper's Shields and The Scarlet Thorns share a fire in Bleakmarsh. Isolde shares a flask.","heroes":["h10","h12","h18","h6","h9"],"parties":["p4","p1"],"loc":"bleakmarsh"},{"id":"e1128","day":29,"season":1,"sday":29,"kind":"party_life","imp":1,"text":"By the third crossroads Ash has stopped waiting and started complaining about the wait.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"bleakmarsh"},{"id":"e1129","day":29,"season":1,"sday":29,"kind":"road","imp":3,"text":"Ash helps a mapmaker on the road to Carrbridge with the lay of the land, and the mapmaker whispers a place worth a visit: The Collapsed Mine.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"bleakmarsh~carrbridge","road_rec":"r195"},{"id":"e1150","day":29,"season":1,"sday":29,"kind":"campfire","imp":1,"text":"Ash orders Juniper an ale before Juniper even sits down. Remembering an order is how it starts.","heroes":["h10","h12"],"parties":["p4"],"loc":"carrbridge"},{"id":"e1158","day":30,"season":1,"sday":30,"kind":"gift","imp":2,"text":"Juniper hands their old Lamplit Brass Lantern to Ash, who has been eyeing it for a week.","heroes":["h10","h12"],"parties":["p4"],"loc":"carrbridge"},{"id":"e1160","day":30,"season":1,"sday":30,"kind":"road","imp":2,"text":"Lady Perpetua Vane calls to Ash for the first time to ask if he would be so kind as to carry a trunk. There is no trunk. There is a hatbox, and it is empty.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"carrbridge~ironhaven","traveller":"perpetua","road_rec":"r197"},{"id":"e1204","day":30,"season":1,"sday":30,"kind":"campfire","imp":1,"text":"Ash talks Isolde through a bad night about fire. Neither mentions it in the morning. Both remember.","heroes":["h12","h18"],"parties":["p4"],"loc":"ironhaven"},{"id":"e1253","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Juniper and Ash, a month into Juniper's Shields: they walk in step now without trying.","heroes":["h10","h12"],"parties":["p4"],"loc":"saltcliffs","wx":"storm"},{"id":"e1254","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Juniper stands in front of Isolde when the arrows start. Isolde notices.","heroes":["h10","h18"],"parties":["p4"],"loc":"saltcliffs","wx":"storm"},{"id":"e1265","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"\"We swear it,\" says every member of Juniper's Shields: never to retreat. Witnessed, written down, and already being bet against.","heroes":["h10","h12","h18"],"parties":["p4"]},{"id":"e1303","day":33,"season":2,"sday":3,"kind":"delve","imp":1,"text":"Juniper's Shields descend into the Sunken Vault, untouched (0%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","wx":"storm"},{"id":"e1304","day":33,"season":2,"sday":3,"kind":"fight","imp":2,"text":"Juniper's Shields handle 3 Cliff Crabs and 2 Drowned in the gatehouse guardroom on floor 1 of the Sunken Vault without much fuss. Before Juniper's Turn Undead it could have gone either way. Loot: 7 chitin, 6 remains, 18 trinkets.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f97","foes":["crab","drowned","drowned"],"where":"in the gatehouse guardroom on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"storm"},{"id":"e1305","day":33,"season":2,"sday":3,"kind":"fight","imp":3,"text":"In the lower guard-post on floor 1 of the Sunken Vault, Juniper's Shields are routed by 2 Sea Serpents and 2 Drowned. Isolde was the last one out and the angriest about it. Juniper has to be dragged out. Injured: Juniper (sprained ankle).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f98","foes":["sea_serpent","drowned","sea_serpent"],"where":"in the lower guard-post on floor 1 of the Sunken Vault","won":false,"close":true,"shape":"place","reworded":14,"wx":"storm"},{"id":"e1306","day":33,"season":2,"sday":3,"kind":"vow_broken","imp":4,"text":"VOW BROKEN. On day 1 of season 2, Juniper's Shields swore never to retreat. Today they ran from a fight.","heroes":["h10","h12","h18"],"parties":["p4"],"cause":"e1265"},{"id":"e1307","day":33,"season":2,"sday":3,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of the Sunken Vault at a push pace: 2 rooms (the gatehouse guardroom, the lower guard-post).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"push","stats":{"rooms":2,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":2,"close":1,"gear":["common"],"fears":2,"wild":[]},"wx":"storm"},{"id":"e1308","day":33,"season":2,"sday":3,"kind":"delve_done","imp":1,"text":"The Sunken Vault wins this round: Juniper's Shields come up after a day at a fast walk, glancing back the whole way. They turned up the gatehouse guardroom, reached floor 1 and cleared 1 room.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","days":1,"bottom":false,"rooms":["the gatehouse guardroom"],"gold":0,"out":"Driven out","turn":"routed","wx":"storm"},{"id":"e1309","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Juniper stitches Ash's arm, then asks how Ash is really doing. The stitches are the quicker job.","heroes":["h10","h12"],"parties":["p4"],"loc":"sunken_vault","skill":"field_chaplain","wx":"storm"},{"id":"e1334","day":33,"season":2,"sday":3,"kind":"campfire","imp":3,"text":"Juniper carries Isolde's pack for the last mile without being asked.","heroes":["h10","h18"],"parties":["p4"],"loc":"sunken_vault","wx":"storm"},{"id":"e1347","day":34,"season":2,"sday":4,"kind":"party_life","imp":3,"text":"Juniper and Isolde ask Ash if the view is nice up there. It is.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","wx":"storm"},{"id":"e1362","day":34,"season":2,"sday":4,"kind":"talent","imp":1,"text":"Juniper walks beside the slowest of the crew all afternoon, talking about nothing in particular.","heroes":["h10"],"parties":["p4"],"loc":"saltcliffs","skill":"field_chaplain","wx":"storm"},{"id":"e1371","day":34,"season":2,"sday":4,"kind":"talent","imp":1,"text":"Isolde sews a lucky charm into the lining of Juniper's coat. Juniper only finds it a week later. Needle and Thread, the guild calls it.","heroes":["h18","h10"],"parties":["p4"],"loc":"saltcliffs","skill":"tailor","wx":"storm"},{"id":"e1397","day":35,"season":2,"sday":5,"kind":"road","imp":3,"text":"Edda Dunmore fishes a pearl out of the Gannet ferry's bait bucket and presses it into Ash's palm, saying the creek has been giving them away since the new moon.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"saltcliffs~saltmarrow","road_rec":"r245"},{"id":"e1414","day":35,"season":2,"sday":5,"kind":"campfire","imp":2,"text":"Ash and Juniper share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h12","h10"],"parties":["p4"],"loc":"saltmarrow","wx":"storm"},{"id":"e1425","day":36,"season":2,"sday":6,"kind":"wagon","imp":3,"text":"Juniper's Shields roll out of Saltmarrow in a donkey cart called Princess, 34 silver between them. Who paid: Ash 18, Juniper 16.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"saltmarrow","wx":"storm"},{"id":"e1427","day":36,"season":2,"sday":6,"kind":"road","imp":3,"text":"Ambrose Nimble deals Ash a hand for buttons. Ash wins, and is cheered by the sparrow on the nearest post.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"saltcliffs~saltmarrow","traveller":"nimble","road_rec":"r249"},{"id":"e1436","day":36,"season":2,"sday":6,"kind":"talent","imp":2,"text":"Ash stands in the road and a runaway cart stops. Not the other way round.","heroes":["h12"],"parties":["p4"],"loc":"saltcliffs","skill":"living_fortress","wx":"storm"},{"id":"e1477","day":37,"season":2,"sday":7,"kind":"ledger","imp":2,"text":"Counters and coin this week: 17 sales, 1,331 silver changing hands. Biggest haul: Tamsin, 165 silver in Ironhaven. Back up from the deep: Juniper's Shields (1 day in the Sunken Vault).","heroes":["h16","h10"],"parties":["p4"]},{"id":"e1483","day":38,"season":2,"sday":8,"kind":"delve","imp":1,"text":"Juniper's Shields descend into the Sunken Vault, barely touched (1%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","wx":"storm"},{"id":"e1484","day":38,"season":2,"sday":8,"kind":"fight","imp":2,"text":"Back in the lower guard-post on floor 1 of the Sunken Vault, Juniper's Shields beat 3 Drowned and a Sea Serpent. The fight turned on Juniper's Turn Undead. Isolde's Caltrops did the damage (2 times). (Brother Toad's blessing on Juniper seems to have held.) Loot: 24 trinkets, 6 remains, 3 drake scales.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f116","foes":["drowned","drowned","drowned"],"where":"in the lower guard-post on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"again","reworded":-6,"wx":"storm"},{"id":"e1485","day":38,"season":2,"sday":8,"kind":"fight","imp":2,"text":"It's 4 Cliff Crabs against Juniper's Shields in the bullion cellar on floor 1 of the Sunken Vault, and it isn't close. The last cliff crab turns tail. That First One Through from Isolde was the moment it tipped. Living Fortress came over Ash at the right moment, as it does. Loot: 6 chitin, 10 cliff crab claws.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f117","foes":["crab","crab","crab"],"where":"in the bullion cellar on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-29,"wx":"storm"},{"id":"e1486","day":38,"season":2,"sday":8,"kind":"gear","imp":3,"text":"In a sealed space off the bullion cellar on floor 1 of the Sunken Vault, Ash finds Knight's Plate of the Long Night and puts it on. Of the Long Night: much braver (+5 nerve). It is a step up from anything Ash could buy.","heroes":["h12"],"parties":["p4"],"loc":"sunken_vault","wx":"storm"},{"id":"e1487","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of the Sunken Vault at a steady pace: 4 rooms (the lower guard-post, the tide-clock, the bullion cellar and 1 more).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":1,"gear":["great"],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1525","day":39,"season":2,"sday":9,"kind":"fight","imp":1,"text":"Ash holds the line as Juniper's Shields dispatch 3 Cliff Crabs in the barnacled quay steps on floor 1 of the Sunken Vault. The last cliff crab bolts. Ash put up Taunt and took the worst of it for the others. Juniper kept them off everyone with Oath of Light. Loot: 7 chitin, 8 fish, 1 trinket.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f121","foes":["crab","crab","crab"],"where":"in the barnacled quay steps on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-22,"wx":"storm"},{"id":"e1526","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of the Sunken Vault at a push pace: 4 rooms (the tide-gate, the assay room, the harbour-light stair and 1 more).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"push","stats":{"rooms":4,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1527","day":39,"season":2,"sday":9,"kind":"night","imp":2,"text":"Something small and clever gets into Juniper's Shields' camp on floor 1 of the Sunken Vault overnight. Isolde wakes up 4 silver and 1 ration lighter.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","wx":"storm"},{"id":"e1540","day":40,"season":2,"sday":10,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of the Sunken Vault at a steady pace: 4 rooms (the weigh-house, the sluice engine room, the silted atrium and 1 more).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":3,"floor":1,"traps":2,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1541","day":40,"season":2,"sday":10,"kind":"ambush","imp":2,"text":"Juniper's Shields wake to a Cliff Crab, a Siren and the Drowned in camp on floor 1 of the Sunken Vault in the middle of the night, and defeat them. The fight was over the moment Juniper's Mark of the Oath landed on the Drowned. Isolde's The First One Through kicked in when it counted. Ash kept the bleeding to a minimum. (Brother Toad's blessing on Ash seems to have held.) Loot: 3 fish, 1 gem, 13 trinkets.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f123","foes":["crab","siren","drowned"],"where":"at their camp on floor 1 of The Sunken Vault, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-11},{"id":"e1567","day":40,"season":2,"sday":10,"kind":"campfire","imp":1,"text":"Juniper and Isolde, a month into Juniper's Shields: they walk in step now without trying.","heroes":["h10","h18"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e1568","day":40,"season":2,"sday":10,"kind":"campfire","imp":1,"text":"A month in Juniper's Shields together. Ash and Isolde know each other's snores, sorrows and orders by heart.","heroes":["h12","h18"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e1602","day":41,"season":2,"sday":11,"kind":"fight","imp":1,"text":"Juniper's Shields, in fine spirits lately, outlast 2 Sirens and the Drowned in the exchange floor on floor 1 of the Sunken Vault. Isolde loosed Repeater, and the siren dropped. Ash saved Bastion for when it mattered. (Brother Toad's blessing on Isolde seems to have held.) Loot: 6 remains, 11 trinkets, 1 gem.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","fight":"f127","foes":["drowned","siren","siren"],"where":"in the exchange floor on floor 1 of the Sunken Vault","won":true,"close":true,"shape":"mood","reworded":-25},{"id":"e1603","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of the Sunken Vault at a cautious pace: 3 rooms (the exchange floor, the sea stairs, green to the waterline, the weigh-house).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":3,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e1632","day":41,"season":2,"sday":11,"kind":"campfire","imp":1,"text":"Ash lets Juniper win at arm-wrestling. Juniper knows, and both let it stand.","heroes":["h12","h10"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e1639","day":41,"season":2,"sday":11,"kind":"goal","imp":1,"text":"After a long night's talk, Juniper's Shields settle on a goal: to find a relic of the old world.","heroes":["h10","h12","h18"],"parties":["p4"]},{"id":"e1653","day":42,"season":2,"sday":12,"kind":"wild_room","imp":3,"text":"Ash and Isolde opened the two-key strongroom in the Sunken Vault on the count of three. They are being very civil about it.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","room":"wild_two_key_strongroom"},{"id":"e1654","day":42,"season":2,"sday":12,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 2 of the Sunken Vault at a cautious pace: 2 rooms (the two-key strongroom, the deposit boxes).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common","common"],"fears":0,"wild":["wild_two_key_strongroom"]}},{"id":"e1665","day":42,"season":2,"sday":12,"kind":"campfire","imp":2,"text":"Juniper carries Ash's pack for the last mile without being asked.","heroes":["h10","h12"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e1672","day":43,"season":2,"sday":13,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 2 of the Sunken Vault at a steady pace: 3 rooms (the old strongroom, the coin vaults, the guards' armoury).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":0,"wild":[]}},{"id":"e1712","day":44,"season":2,"sday":14,"kind":"delve_done","imp":3,"text":"The Sunken Vault, 7 days on: Juniper's Shields come up blinking at the daylight. They came across the tide-clock, a sealed space off the bullion cellar, the two-key strongroom and 3 more good rooms, made it to floor 2, cleared 20 rooms, inked 28% of the map, split 361 silver on the way up and turned back because the rations would only just see them home. Pin it to the board: The Sunken Vault is mostly unexplored (23%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","days":7,"bottom":false,"rooms":["the tide-clock","a sealed space off the bullion cellar"],"gold":361,"turn":"supplies","wx":"fog"},{"id":"e1730","day":44,"season":2,"sday":14,"kind":"talent","imp":1,"text":"Isolde brews tea on a tiny stove at the Sunken Vault, between fights. It's ridiculous. It's exactly right.","heroes":["h18"],"parties":["p4"],"loc":"sunken_vault","skill":"tea_ceremony","wx":"fog"},{"id":"e1795","day":46,"season":2,"sday":16,"kind":"road","imp":3,"text":"Ambrose Nimble teaches Ash three signs that a dealer is cheating, and one more that proves the dealer is just unlucky.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"saltcliffs~saltmarrow","traveller":"nimble","road_rec":"r297"},{"id":"e1825","day":46,"season":2,"sday":16,"kind":"gift","imp":2,"text":"Isolde gives Juniper the Drowned Card. \"For luck,\" Isolde says, and won't explain further.","heroes":["h18","h10"],"parties":["p4"],"loc":"saltmarrow","wx":"fog"},{"id":"e1846","day":47,"season":2,"sday":17,"kind":"night_game","imp":2,"text":"The bandit drops into the road, points at Isolde and says, you, Crooked Cards, one round, loser pays. Isolde wins the last round, and the bandit stares at the table for a long moment before handing over Bandit's Marked Card. Ash says nobody has ever been so politely held up, and is not sure how to feel about it.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"carrbridge","night":"n107","monster_game":"bandit"},{"id":"e1880","day":48,"season":2,"sday":18,"kind":"road","imp":4,"text":"A new road leaves the old one, paved and straight, and no one on the road remembers it. Ash follows it for an hour and finds the same road, a day behind.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"carrbridge~saltmarrow","road_rec":"r318"},{"id":"e1903","day":49,"season":2,"sday":19,"kind":"bounty","imp":2,"text":"Juniper's Shields cash in a season's worth of trophies at the Carrbridge guild: about 78 silver a head.","heroes":["h10"],"parties":["p4"],"loc":"carrbridge","amount":78},{"id":"e1927","day":50,"season":2,"sday":20,"kind":"road","imp":3,"text":"Ash learns from the tinkers how to mend a pot with a spoon and a prayer. The pot holds, which is mostly the prayer.","heroes":["h12","h10","h18"],"parties":["p4"],"road":"carrbridge~ironhaven","traveller":"kettleby","road_rec":"r325"},{"id":"e1941","day":50,"season":2,"sday":20,"kind":"talent","imp":2,"text":"Isolde explains to an Ironhaven table how a deadfall works, using the cutlery. The table is very quiet afterwards.","heroes":["h18"],"parties":["p4"],"loc":"ironhaven","skill":"first_one_through"},{"id":"e1944","day":50,"season":2,"sday":20,"kind":"talent","imp":1,"text":"Ash trades an Ironhaven baker a sourdough starter for a sack of flour. The baker's eyes light up. Chalk it up to Trail Baker.","heroes":["h12"],"parties":["p4"],"loc":"ironhaven","skill":"trail_baker"},{"id":"e1954","day":50,"season":2,"sday":20,"kind":"campfire","imp":2,"text":"Ash once called Isolde's singing a crime. Tonight Ash asks for another verse.","heroes":["h12","h18"],"parties":["p4"],"loc":"ironhaven"},{"id":"e1972","day":51,"season":2,"sday":21,"kind":"talent","imp":1,"text":"Isolde prises the hidden coin open by the fire. Empty. The bandit must have spent what was in it.","heroes":["h18"],"parties":["p4"],"loc":"kingsroad"},{"id":"e1982","day":51,"season":2,"sday":21,"kind":"talent","imp":1,"text":"Juniper picks out the one honest trader at a crossroads market by looking at them all, once.","heroes":["h10"],"parties":["p4"],"loc":"kingsroad","skill":"mark_of_the_oath"},{"id":"e1987","day":51,"season":2,"sday":21,"kind":"campfire","imp":1,"text":"Juniper and Ash find a pear tree by the road and eat far more than is wise.","heroes":["h10","h12"],"parties":["p4"],"loc":"kingsroad"},{"id":"e2005","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"Win number six in a row: Juniper's Shields dispatch 3 Bandit Captains and a Bandit Archer on the King's Road. One Turn Undead from Juniper and two bandit captains were on the ground. Loot: 106 silver each, 22 stolen goods, 1 gem.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"kingsroad","fight":"f150","foes":["bandit_captain","bandit_archer","bandit_captain"],"where":"in The King's Road","won":true,"close":false,"shape":"streak","reworded":-25},{"id":"e2027","day":52,"season":2,"sday":22,"kind":"music","imp":3,"text":"A crew anthem is born: Ash's song. Juniper's Shields sang it under the stars last night, and by the last chorus it was theirs.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"kingsroad","anthem":"hs3"},{"id":"e2028","day":52,"season":2,"sday":22,"kind":"campfire","imp":1,"text":"Ash and Juniper take the late watch together and argue happily about the best road to Ironhaven.","heroes":["h12","h10"],"parties":["p4"],"loc":"kingsroad"},{"id":"e2037","day":52,"season":2,"sday":22,"kind":"big_move","imp":3,"text":"Juniper reaches the crater on the King's Road first and pulls out a lump of star-metal, still warm. On the table: Juniper +57 renown (13th to 9th). Juniper's Shields +51 party renown (4th to 3rd among the crews).","heroes":["h10"],"parties":["p4"],"cause":"e1997","moves":[{"hero":"h10","gain":57,"from":13,"to":9}],"party_moves":[{"party":"p4","gain":51,"from":4,"to":3}]},{"id":"e2042","day":53,"season":2,"sday":23,"kind":"fight","imp":1,"text":"Juniper's Shields see off 2 Bandits and a Bandit Captain on the King's Road without much fuss. Isolde's Caltrops finished the fight. Loot: 39 silver each, 7 stolen goods, 6 bandit sausages.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"kingsroad","fight":"f153","foes":["bandit","bandit","bandit_captain"],"where":"in The King's Road","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e2043","day":53,"season":2,"sday":23,"kind":"fight","imp":1,"text":"It's 3 Wolves against Juniper's Shields on the King's Road, and it isn't close. The last wolf decides enough is enough, and goes. It was Isolde's First One Through that dropped the wolf. Loot: 4 fangs & claws, 1 pelt.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"kingsroad","fight":"f154","foes":["wolf","wolf","wolf"],"where":"in The King's Road","won":true,"close":false,"shape":"foe","reworded":-55},{"id":"e2062","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Ash proves dough in a pot on his hip as he walks. The crew has stopped finding this strange.","heroes":["h12"],"parties":["p4"],"loc":"kingsroad","skill":"trail_baker"},{"id":"e2071","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Isolde spins the hollow coin on a log and listens to it rattle.","heroes":["h18"],"parties":["p4"],"loc":"kingsroad"},{"id":"e2108","day":55,"season":2,"sday":25,"kind":"road","imp":3,"text":"Isolde sits in on rehearsal and learns, by sitting very still, how to harmonise without being noticed.","heroes":["h18","h10","h12"],"parties":["p4"],"road":"carrbridge~saltmarrow","traveller":"off_key","road_rec":"r352"},{"id":"e2164","day":56,"season":2,"sday":26,"kind":"campfire","imp":1,"text":"Ash mends Juniper's bootlace with a bit of string and a great deal of confidence.","heroes":["h12","h10"],"parties":["p4"],"loc":"carrbridge"},{"id":"e2168","day":56,"season":2,"sday":26,"kind":"vow_kept","imp":5,"text":"VOW KEPT. Juniper's Shields find Sunlit Quills in town and pay the debt from day 15 of season 1: a purse of 100 silver and a feast nobody will remember clearly.","heroes":["h10","h12","h18","h11","h20"],"parties":["p4","p2"],"cause":"e531"},{"id":"e2179","day":57,"season":2,"sday":27,"kind":"road","imp":3,"text":"Lark trots past Isolde for the first time, then stops, turns, and walks back. 'Which way is the next town? Quickly.'","heroes":["h18","h10","h12"],"parties":["p4"],"road":"carrbridge~saltmarrow","traveller":"lark","road_rec":"r373"},{"id":"e2213","day":58,"season":2,"sday":28,"kind":"talent","imp":2,"text":"Juniper finds a perfectly good roll of bandages in a ditch near the Salt Cliffs. They decide not to ask why. Scavenger all the way, Juniper insists.","heroes":["h10"],"parties":["p4"],"loc":"saltcliffs","skill":"scavenger"},{"id":"e2220","day":58,"season":2,"sday":28,"kind":"campfire","imp":1,"text":"Juniper patches Isolde's cloak without being asked. Isolde pretends not to notice, then says thanks.","heroes":["h18","h10"],"parties":["p4"],"loc":"saltcliffs"},{"id":"e2245","day":59,"season":2,"sday":29,"kind":"meet","imp":2,"text":"Juniper's Shields run into The Coin of Thornwall on the road between the Salt Cliffs and the Sunken Vault. Stories are exchanged, most of them exaggerated.","heroes":["h10","h12","h18","h1","h8","h16"],"parties":["p4","p6"],"loc":"saltcliffs"},{"id":"e2263","day":60,"season":2,"sday":30,"kind":"delve","imp":1,"text":"Juniper's Shields descend into the Sunken Vault, partly explored (52%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e2264","day":60,"season":2,"sday":30,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 3 of the Sunken Vault at a push pace: 1 room (the cracked foundation).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2296","day":60,"season":2,"sday":30,"kind":"delve_done","imp":1,"text":"The daylight is a shock after a day, and Juniper's Shields come out into it shading every eye. They made it to floor 3.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"sunken_vault","days":1,"bottom":false,"rooms":[],"gold":0},{"id":"e2299","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Juniper's Shields came up short: find a relic of the old world (still looking).","heroes":["h10","h12","h18"],"parties":["p4"]},{"id":"e2350","day":61,"season":3,"sday":1,"kind":"talent","imp":2,"text":"Isolde hands Ash a cup at a roadside halt and doesn't ask what's wrong. Ash says anyway.","heroes":["h18","h12"],"parties":["p4"],"loc":"thornwall","skill":"tea_ceremony"},{"id":"e2357","day":61,"season":3,"sday":1,"kind":"campfire","imp":1,"text":"Isolde and Juniper split the washing-up by a system so complicated that nobody ends up doing any.","heroes":["h18","h10"],"parties":["p4"],"loc":"thornwall"},{"id":"e2397","day":63,"season":3,"sday":3,"kind":"ambush","imp":3,"text":"Juniper's Shields make it nine wins running, beating 2 Kobolds on the road to Redcrag Hills. The last kobold bolts. Juniper's Oath of Light shimmered over the crew at the right moment. Isolde's The First One Through turned the fight. Juniper never let go of Kettle, even when letting go would have been easier. \"Good work. Eat, sleep, go again,\" says Juniper. Loot: 1 silver each, 4 ore.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f178","foes":["kobold","kobold"],"where":"on the road to Redcrag Hills","won":true,"close":false,"shape":"streak","reworded":-30},{"id":"e2412","day":63,"season":3,"sday":3,"kind":"meet","imp":1,"text":"Isolde and Tobias swap stories in Redcrag Hills while Juniper's Shields and The Scarlet Thorns swap rumours.","heroes":["h10","h12","h18","h6","h9"],"parties":["p4","p1"],"loc":"redcrag"},{"id":"e2417","day":63,"season":3,"sday":3,"kind":"talent","imp":1,"text":"Juniper turns the Drowned Card over by the fire. It is cold to the touch, always.","heroes":["h10"],"parties":["p4"],"loc":"redcrag"},{"id":"e2423","day":64,"season":3,"sday":4,"kind":"fight","imp":3,"text":"In Redcrag Hills, 3 Kobolds and a Giant Bat get in Juniper's Shields' way, briefly. The last giant bat breaks and runs. Isolde's Field Ballista was where the fight changed hands. Ask the others what won it: Ash's Living Fortress. Loot: 5 silver each, 7 ore, 4 kobold firepeppers.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f182","foes":["kobold","giant_bat","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"place","reworded":-23},{"id":"e2457","day":65,"season":3,"sday":5,"kind":"fight","imp":1,"text":"Juniper's Shields run into 2 Kobolds in Redcrag Hills and come out on top. Juniper called Oath of Light, and the line steadied. Without Isolde's The First One Through, this goes differently. Loot: 2 silver each, 2 trinkets, a kobold firepepper.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f190","foes":["kobold","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"plain","reworded":-22},{"id":"e2458","day":65,"season":3,"sday":5,"kind":"fight","imp":2,"text":"It's 2 Cave Trolls and a Giant Bat against Juniper's Shields in Redcrag Hills, and it isn't close. That Repeater from Isolde was the moment it tipped. Loot: 20 silver each, 1 fang, a pair of bat wings.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f191","foes":["giant_bat","cave_troll","cave_troll"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e2459","day":65,"season":3,"sday":5,"kind":"ambush","imp":3,"text":"In the middle of the night, 3 Bandits find Juniper's Shields' camp in Redcrag Hills, and Juniper's Shields see them off. Ask anyone when it turned: Isolde's First One Through. Oath of Light came over Juniper at the right moment, as it does. Isolde knew where the next door was before anyone saw it. The old map again. \"The pattern holds,\" says Isolde. Loot: 9 silver each, 3 stolen goods, 6 rations.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f192","foes":["bandit","bandit","bandit"],"where":"at their camp in Redcrag Hills, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-25},{"id":"e2491","day":66,"season":3,"sday":6,"kind":"fight","imp":3,"text":"Juniper's Shields, in fine spirits lately, handle 4 Drakes in Redcrag Hills. The last drake doesn't stay to see the end. Isolde's Field Ballista dropped two drakes before they reached the line. Living Fortress came over Ash at the right moment, as it does. Loot: 6 drake scales, 3 fangs & claws, 6 drake flanks.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f195","foes":["drake","drake","drake"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"mood","reworded":-47},{"id":"e2501","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Juniper sings a walking hymn that matches the crew's pace exactly. The miles go by. Hymn Singer, cast gently, for once.","heroes":["h10"],"parties":["p4"],"loc":"redcrag","skill":"hymn_singer"},{"id":"e2528","day":67,"season":3,"sday":7,"kind":"ambush","imp":2,"text":"Ash holds the line as Juniper's Shields beat 2 Drakes on the road to Ironhaven. Juniper's Mark of the Oath showed everyone where to hit the drake. Ask the others what won it: Isolde's The First One Through. Ash put the wounded ones out of their misery quickly. It's the decent thing. Loot: 1 drake scale, 6 fangs & claws, 3 drake flanks.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"redcrag","fight":"f197","foes":["drake","drake"],"where":"on the road to Ironhaven","won":true,"close":false,"shape":"hero","reworded":-22,"wx":"rain"},{"id":"e2529","day":67,"season":3,"sday":7,"kind":"road","imp":2,"text":"Juniper comes upon Sir Aldous Puddle for the first time reciting the knightly vows to the horse, who has heard them all and is waiting for the part about oats.","heroes":["h10","h12","h18"],"parties":["p4"],"road":"ironhaven~redcrag","traveller":"aldous","road_rec":"r448"},{"id":"e2535","day":67,"season":3,"sday":7,"kind":"meet","imp":2,"text":"Brix and Ash swap stories on the road between Ironhaven and Redcrag Hills while The Coin of Thornwall and Juniper's Shields swap rumours.","heroes":["h1","h8","h16","h10","h12","h18"],"parties":["p6","p4"],"loc":"ironhaven","wx":"rain"},{"id":"e2573","day":68,"season":3,"sday":8,"kind":"talent","imp":2,"text":"Ash sorts out a farmer's toothache at a field gate and is paid in eggs. The words of Tooth Puller, half under his breath.","heroes":["h12"],"parties":["p4"],"loc":"ironhaven","skill":"tooth_puller"},{"id":"e2599","day":69,"season":3,"sday":9,"kind":"boss_race","imp":3,"text":"Two crews, one boss. The Thunder of Frosthold and Juniper's Shields have both set out for Frostspire. The taverns are taking bets.","heroes":["h5","h3","h4","h15","h10","h12","h18"],"parties":["p3","p4"],"loc":"frostspire"},{"id":"e2600","day":69,"season":3,"sday":9,"kind":"talent","imp":1,"text":"A Frosthold card cheat gives up the moment Juniper points across the room. It turns out pointing is enough.","heroes":["h10"],"parties":["p4"],"loc":"frosthold","skill":"mark_of_the_oath"},{"id":"e2612","day":70,"season":3,"sday":10,"kind":"night","imp":2,"text":"Something small and clever gets into Juniper's Shields' camp in Whitepeak Pass overnight. Isolde wakes up 3 silver and 2 rations lighter.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"whitepeak"},{"id":"e2672","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"Juniper's Shields' plan for the season, as told to the barkeep: to earn 450 silver between them before the season ends.","heroes":["h10","h12","h18"],"parties":["p4"]},{"id":"e2680","day":72,"season":3,"sday":12,"kind":"delve","imp":1,"text":"Juniper's Shields descend into Frostspire, mostly unexplored (29%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire"},{"id":"e2681","day":72,"season":3,"sday":12,"kind":"fight","imp":1,"text":"In the wolf run on floor 1 of Frostspire, Juniper's Shields handle 3 Frost Wolves. The last frost wolf doesn't stay to see the end. Isolde's First One Through was where the fight changed hands. Loot: 13 pelts, 4 fangs & claws, 3 wolf haunches. Juniper, who has been afraid of the cold since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","fight":"f207","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"in the wolf run on floor 1 of Frostspire","won":true,"close":false,"shape":"place","reworded":-23},{"id":"e2685","day":72,"season":3,"sday":12,"kind":"fight","imp":3,"text":"Two Ice Golems and 2 Ice Wraiths fall to Juniper's Shields in the frozen guardroom on floor 1 of Frostspire. One Caltrops from Isolde and three of them were on the ground. Ash's Living Fortress kicked in when it counted. Loot: 11 frost crystals, 4 glacier ice.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","fight":"f208","foes":["ice_golem","ice_wraith","ice_golem"],"where":"in the frozen guardroom on floor 1 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-3},{"id":"e2686","day":72,"season":3,"sday":12,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Frostspire at a steady pace: 3 rooms (the wrecked sledge, the wolf run, the frozen guardroom).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":4,"wild":[]}},{"id":"e2699","day":72,"season":3,"sday":12,"kind":"meet","imp":2,"text":"Ash and Morwen swap stories in Frostspire while Juniper's Shields and The Thunder of Frosthold swap rumours.","heroes":["h10","h12","h18","h5","h3","h4","h15"],"parties":["p4","p3"],"loc":"frostspire"},{"id":"e2700","day":72,"season":3,"sday":12,"kind":"talent","imp":2,"text":"A rolling boulder meets Ash. The boulder stops. Ash has a short rest against it. Chalk it up to Immovable.","heroes":["h12"],"parties":["p4"],"loc":"frostspire","skill":"immovable"},{"id":"e2716","day":73,"season":3,"sday":13,"kind":"fight","imp":1,"text":"Juniper's Shields meet 2 Ice Wraiths and a Yeti in the clear-ice room on floor 1 of Frostspire and defeat them. The yeti went down to Juniper's Mark of the Oath. The First One Through did more for this fight than the scoreboard shows. That was Isolde. Loot: 4 ectoplasm, 1 frost crystal, 10 pelts.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","fight":"f209","foes":["ice_wraith","ice_wraith","yeti"],"where":"in the clear-ice room on floor 1 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-14},{"id":"e2717","day":73,"season":3,"sday":13,"kind":"wild_room","imp":3,"text":"A Frostspire yeti has asked, through a series of gestures, for Isolde's recipe.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","room":"wild_yeti_supper"},{"id":"e2718","day":73,"season":3,"sday":13,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 1 of Frostspire at a steady pace: 3 rooms (the clear-ice room, the meltwater seep, the yeti's empty pot).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":["wild_yeti_supper"]}},{"id":"e2719","day":73,"season":3,"sday":13,"kind":"talent","imp":1,"text":"Juniper leans against Ash to sleep. Then two more partymates do.","heroes":["h12","h10"],"parties":["p4"],"loc":"frostspire","skill":"immovable"},{"id":"e2726","day":73,"season":3,"sday":13,"kind":"talent","imp":1,"text":"Juniper checks behind the loose stone everyone else walked past. There's a coil of good rope behind it. Scavenger, the way the old trappers taught it.","heroes":["h10"],"parties":["p4"],"loc":"frostspire","skill":"scavenger"},{"id":"e2741","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2742","day":74,"season":3,"sday":14,"kind":"talent","imp":1,"text":"Isolde mends Ash's spectacles with wire, a bead and a lot of squinting. Tinker's Bench: one of the things Isolde learned the long way round.","heroes":["h18","h12"],"parties":["p4"],"loc":"frostspire","skill":"tinkers_bench"},{"id":"e2743","day":74,"season":3,"sday":14,"kind":"night","imp":2,"text":"A woman with a lantern and no luggage walks into Juniper's Shields' camp on floor 2 of Frostspire, asks the way to Emberdeep, and leaves the firelight in the wrong direction.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire"},{"id":"e2793","day":75,"season":3,"sday":15,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2794","day":75,"season":3,"sday":15,"kind":"delve_done","imp":3,"text":"Frostspire is behind Juniper's Shields now: 4 days down there, and the sky looks enormous. They reached floor 2, turned up the wrecked sledge and the yeti's empty pot, took 6 rooms off the map's blank side, split 34 silver on the way up and turned back because the way on beat them twice, and they mean to come back with more.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"frostspire","days":4,"bottom":false,"rooms":["the wrecked sledge","the yeti's empty pot"],"gold":34,"turn":"blocked"},{"id":"e2795","day":75,"season":3,"sday":15,"kind":"ability","imp":2,"text":"By the fire at Frostspire, Isolde builds a trinket out of rivets and a hinge: a small clockwork frog that hops once and looks proud.","heroes":["h18"],"parties":["p4"],"loc":"frostspire","skill":"tinkers_bench","sk":"Tinker's Bench","rule":true},{"id":"e2811","day":75,"season":3,"sday":15,"kind":"talent","imp":1,"text":"Juniper checks every wound in the crew, one by one, whether its owner likes it or not. They heal anyway.","heroes":["h10"],"parties":["p4"],"loc":"frostspire","skill":"house_calls"},{"id":"e2826","day":76,"season":3,"sday":16,"kind":"road","imp":4,"text":"A silent old champion plays chess at a milestone on the road to Whitepeak Pass against anyone who stops. Juniper sits down, plays the game of their life, and is told it was a good one.","heroes":["h10","h12","h18"],"parties":["p4"],"road":"frostspire~whitepeak","road_rec":"r508"},{"id":"e2827","day":76,"season":3,"sday":16,"kind":"night","imp":2,"text":"Ash's ghost story in Whitepeak Pass ends with \"...and it was standing right behind them.\" Isolde does not look behind her once, all night.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"whitepeak"},{"id":"e2866","day":77,"season":3,"sday":17,"kind":"road","imp":2,"text":"Osk is sitting on a milestone doing sums when Juniper passes for the first time. He hides the ledger very fast.","heroes":["h10","h12","h18"],"parties":["p4"],"road":"frosthold~whitepeak","traveller":"osk","road_rec":"r518"},{"id":"e2884","day":77,"season":3,"sday":17,"kind":"goal_progress","imp":2,"text":"Juniper's Shields are getting close: earn 450 silver between them before the season ends (273 of 450 silver).","heroes":["h10","h12","h18"],"parties":["p4"]},{"id":"e2903","day":78,"season":3,"sday":18,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Cindervast the Hoardmother: Juniper's Shields and The Tidal Ledger. Odds are offered, mostly on whoever's buying.","heroes":["h10","h12","h18","h7","h19","h2","h14"],"parties":["p4","p7"],"loc":"emberdeep"},{"id":"e2904","day":78,"season":3,"sday":18,"kind":"talent","imp":2,"text":"A Veldrock brawler tries to throw Ash out of the tavern. After a while the brawler sits down next to him.","heroes":["h12"],"parties":["p4"],"loc":"veldrock","skill":"immovable"},{"id":"e2917","day":78,"season":3,"sday":18,"kind":"goal_done","imp":4,"text":"GOAL: Juniper's Shields set out to earn 450 silver between them before the season ends, and they have done it, with 12 days to spare. XP: Juniper +960, Ash +1000, Isolde +960.","heroes":["h10","h12","h18"],"parties":["p4"],"xp":{"h10":960,"h12":1000,"h18":960}},{"id":"e2932","day":79,"season":3,"sday":19,"kind":"talent","imp":1,"text":"Juniper plants the banner by the tent. It falls over in the night. Juniper replants it, louder. That's Banner Forward for you.","heroes":["h10"],"parties":["p4"],"loc":"emberdeep","skill":"banner_forward"},{"id":"e2955","day":79,"season":3,"sday":19,"kind":"meet","imp":1,"text":"Juniper's Shields warn The Tidal Ledger about what's lurking in Emberdeep. The Tidal Ledger pretends to already know.","heroes":["h10","h12","h18","h7","h19","h2","h14"],"parties":["p4","p7"],"loc":"emberdeep"},{"id":"e2957","day":79,"season":3,"sday":19,"kind":"gift","imp":2,"text":"By the fire, Isolde quietly hands Juniper a Bandit's Marked Card. Juniper pockets it like it's treasure.","heroes":["h18","h10"],"parties":["p4"],"loc":"emberdeep"},{"id":"e2973","day":80,"season":3,"sday":20,"kind":"delve","imp":1,"text":"Juniper's Shields descend into Emberdeep, partly explored (41%).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep"},{"id":"e2974","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 3 of Emberdeep at a push pace: 1 room (the tong racks).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep","pace":"push","stats":{"rooms":1,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2975","day":80,"season":3,"sday":20,"kind":"ability","imp":2,"text":"Isolde sits up late at Emberdeep with a pocketknife and the day's broken bits. By midnight there's a trinket: a tiny brass beetle that walks in a straight line.","heroes":["h18"],"parties":["p4"],"loc":"emberdeep","skill":"tinkers_bench","sk":"Tinker's Bench","rule":true},{"id":"e2991","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"A boulder rolls down the ramp. Ash puts out one hand. Ash puts it down to Living Fortress.","heroes":["h12"],"parties":["p4"],"loc":"emberdeep","skill":"living_fortress"},{"id":"e2999","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"Juniper makes Ash stop walking on a twisted ankle. Ash complains, sits down, and is better by morning. The words of Medic, half under their breath.","heroes":["h10","h12"],"parties":["p4"],"loc":"emberdeep","skill":"medic"},{"id":"e3016","day":81,"season":3,"sday":21,"kind":"trap","imp":2,"text":"Isolde springs a flame vent in a ramp of black glass beside the lava-fall on floor 3 of Emberdeep (deep cut).","heroes":["h18"],"parties":["p4"],"loc":"emberdeep"},{"id":"e3017","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 3 of Emberdeep at a push pace: 3 rooms (a ramp of black glass beside the lava-fall, the chamber of melted crowns, the cinder causeway).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep","pace":"push","stats":{"rooms":3,"size":3,"floor":3,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e3049","day":82,"season":3,"sday":22,"kind":"fight","imp":3,"text":"In the obsidian gallery on floor 4 of Emberdeep, Juniper's Shields are routed by 2 Lava Golems and a Fire Elemental. Juniper was the last one out and the angriest about it. Ash has to be dragged out. Injured: Ash (concussion). Isolde's oldest fear, fire, wins this one.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep","fight":"f229","foes":["lava_golem","fire_elemental","lava_golem"],"where":"in the obsidian gallery on floor 4 of Emberdeep","won":false,"close":true,"shape":"place","reworded":14},{"id":"e3050","day":82,"season":3,"sday":22,"kind":"delve_day","imp":1,"text":"Juniper's Shields work floor 4 of Emberdeep at a steady pace: 2 rooms (the golem works, the obsidian gallery).","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"size":3,"floor":4,"traps":0,"sprung":0,"trap_inj":0,"uncleared":2,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]}},{"id":"e3051","day":82,"season":3,"sday":22,"kind":"delve_done","imp":1,"text":"Juniper's Shields climb out after 3 days with something unfriendly close behind and no wish to discuss it. They got all the way to the bottom, found the chamber of melted crowns, worked through 5 rooms and came away with 79 silver between them.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep","days":3,"bottom":true,"rooms":["the chamber of melted crowns"],"gold":79,"out":"Driven out","turn":"routed"},{"id":"e3053","day":82,"season":3,"sday":22,"kind":"talent","imp":2,"text":"Isolde sleeps on the side of the fire nearest Ash. Everyone does now. That's Living Fortress for you.","heroes":["h12","h18"],"parties":["p4"],"loc":"emberdeep","skill":"living_fortress"},{"id":"e3054","day":82,"season":3,"sday":22,"kind":"night","imp":2,"text":"Juniper tells a ghost story by the fire outside Emberdeep. Isolde sleeps with a hand on her weapon.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"emberdeep"},{"id":"e3133","day":83,"season":3,"sday":23,"kind":"talent","imp":1,"text":"Juniper visits the sick on three streets of Veldrock before lunch and is sent off with a basket of eggs.","heroes":["h10"],"parties":["p4"],"loc":"veldrock","skill":"house_calls"},{"id":"e3141","day":83,"season":3,"sday":23,"kind":"campfire","imp":2,"text":"Isolde orders Juniper an ale before Juniper even sits down. Remembering an order is how it starts.","heroes":["h10","h18"],"parties":["p4"],"loc":"veldrock"},{"id":"e3174","day":85,"season":3,"sday":25,"kind":"road","imp":3,"text":"Little Dill whispers to Juniper that Eustace's pike has been seen near Emberdeep, and that nobody has dared go and look since.","heroes":["h10","h12","h18"],"parties":["p4"],"road":"frosthold~ironhaven","traveller":"wet_boots","road_rec":"r584"},{"id":"e3189","day":85,"season":3,"sday":25,"kind":"talent","imp":2,"text":"Juniper pours a capful of homebrew for Isolde at a rest stop. Isolde coughs, then holds the cup out again.","heroes":["h10","h18"],"parties":["p4"],"loc":"ironhaven","skill":"brewer"},{"id":"e3230","day":86,"season":3,"sday":26,"kind":"road","imp":2,"text":"The bees on the road to Frosthold take Isolde's attempt on their honey very hard indeed. Isolde runs the last field with a cloud behind.","heroes":["h18","h10","h12"],"parties":["p4"],"road":"frosthold~ironhaven","road_rec":"r591"},{"id":"e3238","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"The Frosthold guard asks Ash to stand at the gate for one afternoon. Crime drops.","heroes":["h12"],"parties":["p4"],"loc":"frosthold","skill":"living_fortress","wx":"snow"},{"id":"e3250","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"Juniper trips a wire on the way to the privy. A bell rings. Isolde wakes and says 'that's one'. Somebody asks how. 'The First One Through,' says Isolde.","heroes":["h18","h10"],"parties":["p4"],"loc":"whitepeak","skill":"first_one_through","wx":"snow"},{"id":"e3251","day":87,"season":3,"sday":27,"kind":"ability","imp":2,"text":"Isolde finds a broken goblin trinket in the grass at Whitepeak Pass, mends it, improves it and teaches it a tune. She keeps a trinket and the idea behind it.","heroes":["h18"],"parties":["p4"],"loc":"whitepeak","skill":"tinkers_bench","sk":"Tinker's Bench","rule":true,"wx":"snow"},{"id":"e3279","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"Juniper sings an evening hymn by the fire. Even Ash, a sceptic, hums the last line. One quiet Hymn Singer, and done.","heroes":["h10","h12"],"parties":["p4"],"loc":"whitepeak","skill":"hymn_singer","wx":"snow"},{"id":"e3298","day":88,"season":3,"sday":28,"kind":"fight","imp":1,"text":"Juniper's Shields send 2 Ice Wraiths back to their rest in Whitepeak Pass. Juniper finished the ice wraith with Mark of the Oath and leaned on their weapon, breathing hard. Juniper kept them off everyone with Oath of Light. Loot: 9 ectoplasm, 3 frost crystals, 4 wraith-frost.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"whitepeak","fight":"f253","foes":["ice_wraith","ice_wraith"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"foe","reworded":-17,"wx":"snow"},{"id":"e3299","day":88,"season":3,"sday":28,"kind":"fight","imp":1,"text":"Juniper's Shields dispatch a Yeti and an Ice Wraith in Whitepeak Pass, again. Nobody invited the wraiths. They came anyway, drawn by the noise, and made it everyone's problem. Isolde's Repeater finished the fight. Loot: 10 pelts, 4 yeti steaks, 4 ectoplasm.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"whitepeak","fight":"f254","foes":["yeti","ice_wraith"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"again","reworded":-7,"wx":"snow"},{"id":"e3303","day":88,"season":3,"sday":28,"kind":"meet","imp":2,"text":"Morwen and Ash swap stories in Whitepeak Pass while The Thunder of Frosthold and Juniper's Shields swap rumours.","heroes":["h5","h3","h4","h15","h10","h12","h18"],"parties":["p3","p4"],"loc":"whitepeak","wx":"snow"},{"id":"e3314","day":88,"season":3,"sday":28,"kind":"ledger","imp":2,"text":"The week's trade: 21 packs emptied onto counters for 2,318 silver. Biggest haul: Vex, 245 silver in Veldrock. Back up from the deep: Juniper's Shields (3 days in Emberdeep), Sunlit Quills (2 days in the Sunken Vault), The Thunder of Frosthold (3 days in Frostspire), The Coin of Thornwall (3 days in the Sunken Vault).","heroes":["h7","h10","h11","h5"],"parties":["p4","p2","p3"]},{"id":"e3322","day":89,"season":3,"sday":29,"kind":"fight","imp":2,"text":"Juniper's Shields, in fine spirits lately, see off 3 Frost Wolves in Whitepeak Pass. The last frost wolf decides enough is enough, and goes. Ash put up Bastion and took the worst of it for the others. Isolde's The First One Through kicked in when it counted. Loot: 9 pelts, 3 fangs & claws, 3 wolf haunches.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"whitepeak","fight":"f256","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"mood","reworded":-54,"wx":"snow"},{"id":"e3338","day":89,"season":3,"sday":29,"kind":"campfire","imp":2,"text":"Juniper and Ash reach a truce over the good blanket: alternate nights, strictly kept, frequently cheated.","heroes":["h10","h12"],"parties":["p4"],"loc":"whitepeak","wx":"snow"},{"id":"e3353","day":90,"season":3,"sday":30,"kind":"fight","imp":2,"text":"Isolde hits hardest as Juniper's Shields beat 2 Frost Wolves and a Yeti in Whitepeak Pass. Isolde's Field Ballista took most of the fight out of the frost wolf in one go. Loot: 19 pelts, 6 fangs & claws, 6 wolf haunches.","heroes":["h10","h12","h18"],"parties":["p4"],"loc":"whitepeak","fight":"f257","foes":["frost_wolf","yeti","frost_wolf"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"hero","reworded":-23,"wx":"storm"}],"roles":{"h10":"Leader · Scout","h12":"Shield","h18":"Quartermaster"},"quest":{"what":"Hunt","where":"Whitepeak Pass","why":"bounties and pelts, risk slight","floor":null,"floors":null},"tactics":{"front":["h10","h12"],"back":["h18"],"plan":"Juniper and Ash hold the front; Isolde picks off whatever gets close.","traits":{"boldness":0.16,"risk":0.15,"greed":-0.01,"sociability":0.2,"honor":0.13,"curiosity":0.07,"temper":-0.24,"loyalty":0.54},"mix":"2 blades, 1 bow","notes":["No healer: every wound comes home with them.","Mostly steel: slow, sturdy, hard to shift."],"style":["brawlers"],"skills":[{"label":"Damage","skills":[{"hero":"h10","id":"mark_of_the_oath","name":"Mark of the Oath","desc":"Points at the worst one in the room. Everyone follows the finger.","tags":[],"rank":1,"uses":31},{"hero":"h12","id":"sunder","name":"Sunder","desc":"Aims for the gaps in armor.","tags":[],"rank":1,"uses":21},{"hero":"h18","id":"caltrops","name":"Caltrops","desc":"A handful of spikes, scattered where feet go.","tags":["craft","stealth"],"rank":2,"uses":21},{"hero":"h18","id":"repeater","name":"Repeater","desc":"Built from a mousetrap and spite. Fires three.","tags":["craft"],"rank":2,"uses":16},{"hero":"h10","id":"turn_undead","name":"Turn Undead","desc":"Begone.","tags":["holy"],"rank":3,"uses":14},{"hero":"h10","id":"judgement","name":"Judgement","desc":"The verdict is in. It is heavy.","tags":["holy"],"rank":1,"uses":7},{"hero":"h10","id":"radiance","name":"Radiance","desc":"A flash of holy light, right in the eyes.","tags":["holy"],"rank":3,"uses":6},{"hero":"h18","id":"field_ballista","name":"Field Ballista","desc":"Assembled in four minutes. Disassembles goblins in one.","tags":["craft"],"rank":2,"uses":6},{"hero":"h10","id":"smite","name":"Smite","desc":"Radiant and righteous. Double against the dead.","tags":["holy"],"rank":1,"uses":5},{"hero":"h18","id":"bear_trap","name":"Bear Trap","desc":"Sprung, clamped, and very sorry for itself.","tags":["craft"],"rank":1,"uses":0}]},{"label":"Defence","skills":[{"hero":"h12","id":"taunt","name":"Taunt","desc":"Insults their mother. Every enemy turns.","tags":["guard"],"rank":2,"uses":27},{"hero":"h18","id":"tailwind","name":"Tailwind","desc":"The wind is suddenly on everyone's side.","tags":["storm","travel"],"rank":1,"uses":25},{"hero":"h12","id":"bastion","name":"Bastion","desc":"Plants the shield. Everything behind it is somebody else's problem.","tags":["guard"],"rank":2,"uses":18},{"hero":"h10","id":"divine_shield","name":"Divine Shield","desc":"Golden light, briefly.","tags":["holy","guard"],"rank":2,"uses":12}]},{"label":"Tricks","skills":[{"hero":"h10","id":"oath_of_light","name":"Oath of Light","desc":"Says the oath before the first blow. The oath is long. The armour holds.","tags":["holy"],"rank":2,"uses":29},{"hero":"h18","id":"first_one_through","name":"The First One Through","desc":"Rigged the clearing before anyone else arrived. Is very polite about it.","tags":[],"rank":1,"uses":28},{"hero":"h18","id":"trip_wire","name":"Trip Wire","desc":"Strung across the path before anyone noticed.","tags":["craft","stealth"],"rank":3,"uses":14},{"hero":"h12","id":"living_fortress","name":"Living Fortress","desc":"Sieges have been called off on sight of them.","tags":[],"rank":1,"uses":11},{"hero":"h10","id":"banner_forward","name":"Banner Forward","desc":"Plants the banner first and asks questions never.","tags":[],"rank":1,"uses":6},{"hero":"h12","id":"unbreakable","name":"Unbreakable","desc":"Gets harder to kill as they get closer to dying.","tags":["guard"],"rank":2,"uses":3},{"hero":"h12","id":"immovable","name":"Immovable","desc":"Not stubborn. Just very, very heavy, all the way through.","tags":[],"rank":1,"uses":1},{"hero":"h12","id":"rooted_stance","name":"Rooted Stance","desc":"Not stubborn. Just extremely there.","tags":["guard"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h10","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":1,"uses":0},{"hero":"h12","id":"arcane_edge","name":"Arcane Edge","desc":"Runes along the blade hum.","tags":["arcane"],"rank":1,"uses":0},{"hero":"h12","id":"bulwark","name":"Bulwark","desc":"A wall that walks.","tags":["guard"],"rank":1,"uses":0},{"hero":"h12","id":"fortress","name":"Fortress","desc":"Siege engines have bounced off them.","tags":["guard"],"rank":1,"uses":0},{"hero":"h18","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":2,"uses":0}]},{"label":"On the road","skills":[{"hero":"h10","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":2,"uses":0},{"hero":"h10","id":"medic","name":"Medic","desc":"Injuries heal faster in their party.","tags":["heal"],"rank":1,"uses":0},{"hero":"h10","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h10","id":"hymn_singer","name":"Hymn Singer","desc":"Sings the old hymns in a voice like a warm bath.","tags":["holy","music"],"rank":1,"uses":0},{"hero":"h10","id":"scavenger","name":"Scavenger","desc":"Checks every pocket, every boot, every crevice.","tags":[],"rank":1,"uses":0},{"hero":"h10","id":"field_chaplain","name":"Field Chaplain","desc":"Patches the cut, then asks how they're really doing.","tags":["heal","holy"],"rank":1,"uses":0},{"hero":"h10","id":"house_calls","name":"House Calls","desc":"Visits the sick in every town. Starts with the crew.","tags":["heal","holy"],"rank":1,"uses":0},{"hero":"h12","id":"tooth_puller","name":"Tooth Puller","desc":"Village dentist. Steady hand, strong string.","tags":["heal"],"rank":1,"uses":0},{"hero":"h12","id":"rumourmonger","name":"Rumourmonger","desc":"Hears everything first. Repeats most of it.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h12","id":"bouncer","name":"Bouncer","desc":"Stands in doorways, professionally.","tags":["guard"],"rank":3,"uses":0},{"hero":"h12","id":"sentry","name":"Sentry","desc":"Hears the twig snap before the twig does.","tags":["guard"],"rank":2,"uses":0},{"hero":"h12","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h12","id":"night_watch","name":"Night Watch","desc":"Takes every watch so nobody else has to. The crew wakes up mended.","tags":["guard"],"rank":1,"uses":0},{"hero":"h12","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h18","id":"carpenter","name":"Carpentry","desc":"Measures twice, cuts once, builds a bench.","tags":["craft"],"rank":2,"uses":0},{"hero":"h18","id":"tailor","name":"Needle and Thread","desc":"Mends cloaks, patches tents, takes in trousers.","tags":["craft"],"rank":1,"uses":0},{"hero":"h18","id":"hedge_wizard","name":"Hedge Wizardry","desc":"Fixes kettles with spells and spells with kettles.","tags":["arcane","craft"],"rank":1,"uses":0},{"hero":"h18","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h18","id":"tea_ceremony","name":"Tea Ceremony","desc":"Nothing is so bad it can't wait for the kettle.","tags":[],"rank":1,"uses":0},{"hero":"h18","id":"fletcher","name":"Fletcher","desc":"Every arrow straight, every feather matched.","tags":["craft","crit"],"rank":1,"uses":0},{"hero":"h18","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h18","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h10","dmg":3173,"healed":0,"taken":428,"kills":11,"row":"front"},{"hero":"h12","dmg":462,"healed":0,"taken":590,"kills":2,"row":"front"},{"hero":"h18","dmg":4857,"healed":0,"taken":247,"kills":23,"row":"back"}],"ground":{"name":"The Sunken Vault","fights":7}},"trophies":[]};